// M28: the held-out generation sets, selected by a committed rule from Peace's public commits only.
// The selection is fixed before any generation run and is regenerated by bin/heldout-select.ts (and its test)
// from the public clones at the pinned heads below; nothing here reads private code.
import { createHash } from "node:crypto";

export const HELDOUT_SCHEMA = "peaceai-heldout:v1";
/** The author the miners count as Peace (lib/minetest.ts PEACE_AUTHOR). */
export const HELDOUT_AUTHOR = "301894882+PeaceG03@users.noreply.github.com";
/** Public repositories and the heads the selection was fixed at (last commit at or before fixedAt). */
export const HELDOUT_HEADS: Readonly<Record<string, string>> = {
  "PeaceG03/PeaceAI-Workspace": "c44d7130b8488032e033dcfa3477a9daa68517ec",
  "PeaceG03/PeaceSTOCKS": "58fdb6cb6ef64ea9c4db609c09e6e77288e86dd5",
};
export const HELDOUT_RULE = [
  "Candidates: every non-merge commit by HELDOUT_AUTHOR reachable from HELDOUT_HEADS[repo], in both public repos.",
  "two-file: the commit adds/modifies exactly 2 non-test .ts files and touches exactly 1 test .ts file (a test is *.test.ts or under a test/ directory), with no deleted non-test .ts file.",
  "expression-edit: the M27 body miner (lib/minebody.ts mineBody, #136) records at least one EXPR_REPLACE observation for the commit.",
  "Held out: every commit with either kind (kind 'two-file+expression-edit' when both).",
  "Set: sha256('peaceai-heldout:v1:' + repo + '@' + sha), first byte even -> A (measured during development), odd -> B (untouched; final pass rate only).",
  "Exclusion: both sets are excluded from every training corpus by path (same source) and by content sha256 (any source): every blob of a touched path at the commit, at its parent and at the pinned head.",
].join("\n");

export type HeldOutKind = "two-file" | "expression-edit" | "two-file+expression-edit";
export interface HeldOutEntry { repo: string; sha: string; kind: HeldOutKind; paths: string[]; contentSha256: string[] }

export const isTestPath = (p: string): boolean => /\.test\.ts$/.test(p) || /(?:^|\/)test\//.test(p);

/** two-file from `git show --name-status --no-renames` lines ("M\tpath"). */
export function isTwoFile(nameStatus: readonly string[]): boolean {
  const ns = nameStatus.filter(Boolean).map((l) => { const [s, p] = l.split("\t"); return { s: s!, p: p! }; });
  const src = ns.filter((x) => x.p.endsWith(".ts") && !isTestPath(x.p));
  const tests = ns.filter((x) => x.p.endsWith(".ts") && isTestPath(x.p));
  return src.length === 2 && tests.length === 1 && src.every((x) => x.s === "A" || x.s === "M");
}

export function kindOf(twoFile: boolean, expression: boolean): HeldOutKind | null {
  return twoFile && expression ? "two-file+expression-edit" : twoFile ? "two-file" : expression ? "expression-edit" : null;
}

export function setOf(repo: string, sha: string): "A" | "B" {
  return createHash("sha256").update(`${HELDOUT_SCHEMA}:${repo}@${sha}`).digest()[0]! % 2 === 0 ? "A" : "B";
}

/** Builds the committed file from classified entries (order: repo, then sha). */
export function buildHeldOut(entries: readonly HeldOutEntry[], fixedAt: string) {
  const sorted = [...entries].sort((a, b) => (a.repo + a.sha < b.repo + b.sha ? -1 : 1));
  return {
    schema: HELDOUT_SCHEMA, fixedAt, rule: HELDOUT_RULE, author: HELDOUT_AUTHOR, heads: HELDOUT_HEADS,
    sets: { A: sorted.filter((e) => setOf(e.repo, e.sha) === "A"), B: sorted.filter((e) => setOf(e.repo, e.sha) === "B") },
  };
}

export const sha256Hex = (b: Buffer | string): string => createHash("sha256").update(b).digest("hex");

// ---- M33: held-out set C (Architect option 3): single-file source+test edits, carved AFTER this rule is committed.
export const HELDOUT_C_SCHEMA = "peaceai-heldout-c:v1";
/** Heads set C is selected at (public main when the rule was committed). */
export const HELDOUT_C_HEADS: Readonly<Record<string, string>> = {
  "PeaceG03/PeaceAI-Workspace": "cc9b4a616782c8a0d83c4405833c5ee14ead645f",
  "PeaceG03/PeaceSTOCKS": "a3d9484d0c5cdbed67efd62356ec2324c132ac82",
};
export const HELDOUT_C_RULE = [
  "Candidates: every non-merge commit by HELDOUT_AUTHOR reachable from HELDOUT_C_HEADS[repo], in both public repos, that is NOT in heldout.json set A or B.",
  "source+test: the commit touches exactly 1 non-test .ts file and exactly 1 test .ts file (a test is *.test.ts or under a test/ directory), both added or modified (no delete), and nothing else.",
  "Held out: every candidate of that kind is set C (one set, final rate only; never measured during development).",
  "Exclusion: set C is excluded from every training corpus by content sha256 (any source): every blob of a touched path at the commit, at its parent and at the pinned C head.",
].join("\n");

/** source+test from `git show --name-status --no-renames` lines: exactly one source .ts and one test .ts, A/M only, nothing else. */
export function isSourceTest(nameStatus: readonly string[]): boolean {
  const ns = nameStatus.filter(Boolean).map((l) => { const [s, p] = l.split("\t"); return { s: s!, p: p! }; });
  if (ns.length !== 2 || !ns.every((x) => (x.s === "A" || x.s === "M") && x.p.endsWith(".ts"))) return false;
  return ns.filter((x) => isTestPath(x.p)).length === 1;
}

export interface HeldOutCEntry { repo: string; sha: string; kind: "source+test"; paths: string[]; contentSha256: string[] }
/** Builds the committed set C file (order: repo, then sha). */
export function buildHeldOutC(entries: readonly HeldOutCEntry[], fixedAt: string) {
  const sorted = [...entries].sort((a, b) => (a.repo + a.sha < b.repo + b.sha ? -1 : 1));
  return { schema: HELDOUT_C_SCHEMA, fixedAt, rule: HELDOUT_C_RULE, author: HELDOUT_AUTHOR, heads: HELDOUT_C_HEADS, sets: { C: sorted } };
}
